#!/bin/bash
#=============================================================================
# run_atpg.sh - Modus stuck-at ATPG on the scan netlist (same as ALU_32b)
# Uses the script generated by Genus write_dft_atpg in dft_run/test_scripts/
#=============================================================================
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "$SCRIPT_DIR/../flow_config.sh" || exit 1
cd "$SCRIPT_DIR/dft_run" || exit 1
mkdir -p logs
modus -file test_scripts/runmodus.atpg.tcl 2>&1 | tee logs/modus_atpg.log
echo "------------------------------------------------------------"
grep -iE "Test Coverage|Adjusted|Faults|#Faults|Global Statistics" -A0 logs/modus_atpg.log | head -20
echo "Detailed logs: dft_run/test_scripts/testresults/logs/"
